  background:
    linear-gradient(180deg, rgba(75, 0, 16, 0.9) 0%, rgba(20, 5, 7, 0.98) 28%),
    var(--bg-secondary);
  color: var(--text-primary);
  font-family: var(--font-body), sans-serif;
  text-rendering: optimizeLegibility;
}

:where(a[href], button, input, textarea, select, summary):focus-visible {
