  position: fixed;
  left: 1rem;
  top: 1rem;
  z-index: 70;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: var(--bg-surface);
  color: var(--text-on-light);
  padding: 0.875rem 1.25rem;
