import Image from "next/image";
import Link from "next/link";

import heroContent from "@/data/hero.json";

type HeroLink = {
  text: string;
  link: string;
};

type HeroHighlight = {
  label: string;
  description: string;
};

type HeroVisual = {
  src: string;
  alt: string;
  eyebrow: string;
  caption: string;
};

type HeroContent = {
  name: string;
  greeting: string;
  titleLines: string[];
  description: string;
  cta: HeroLink;
  secondaryCta: HeroLink;
  highlights: HeroHighlight[];
  visual: HeroVisual;
};

