  await mobilePage.goto('http://127.0.0.1:3100', { waitUntil: 'networkidle' });
  await mobilePage.screenshot({ path: 'test-results/story-010-mobile.png', fullPage: true });

  console.log(JSON.stringify({ faqHiddenStates }, null, 2));

  await desktop.close();
  await mobile.close();
  await browser.close();
})();
